import unittest
import codec


class ParseEventTests(unittest.TestCase):
    def test_restock(self):
        ev = codec.parse_event('{"id":"a","op":"restock","sku":"S","qty":5}')
        self.assertEqual(ev, {'id': 'a', 'op': 'restock', 'sku': 'S', 'qty': 5})

    def test_whitespace_surrounding(self):
        ev = codec.parse_event('  {"id":"a","op":"restock","sku":"S","qty":1}  ')
        self.assertEqual(ev['id'], 'a')

    def test_reserve_sorts_and_aggregates(self):
        ev = codec.parse_event(
            '{"id":"r","op":"reserve","request":"req","lines":[["b",2],["a",1],["b",3]]}')
        self.assertEqual(ev['lines'], [['a', 1], ['b', 5]])

    def test_reserve_empty_lines(self):
        ev = codec.parse_event('{"id":"r","op":"reserve","request":"req","lines":[]}')
        self.assertEqual(ev['lines'], [])

    def test_cancel(self):
        ev = codec.parse_event('{"id":"c","op":"cancel","request":"req"}')
        self.assertEqual(ev, {'id': 'c', 'op': 'cancel', 'request': 'req'})

    def test_preserves_strings_exactly(self):
        ev = codec.parse_event(
            '{"id":"a b\\\\c|d","op":"restock","sku":" x | \\u00e9 ","qty":1}')
        self.assertEqual(ev['id'], 'a b\\c|d')
        self.assertEqual(ev['sku'], ' x | \u00e9 ')

    def test_rejects_non_string(self):
        with self.assertRaises(ValueError):
            codec.parse_event(42)

    def test_rejects_malformed_json(self):
        with self.assertRaises(ValueError):
            codec.parse_event('{bad')

    def test_rejects_non_object(self):
        with self.assertRaises(ValueError):
            codec.parse_event('[1,2]')

    def test_rejects_extra_field(self):
        with self.assertRaises(ValueError):
            codec.parse_event('{"id":"a","op":"restock","sku":"S","qty":1,"x":2}')

    def test_rejects_missing_field(self):
        with self.assertRaises(ValueError):
            codec.parse_event('{"id":"a","op":"restock","qty":1}')

    def test_rejects_unknown_op(self):
        with self.assertRaises(ValueError):
            codec.parse_event('{"id":"a","op":"nope","sku":"S","qty":1}')

    def test_rejects_duplicate_keys(self):
        with self.assertRaises(ValueError):
            codec.parse_event('{"id":"a","id":"b","op":"restock","sku":"S","qty":1}')

    def test_rejects_boolean_quantity(self):
        with self.assertRaises(ValueError):
            codec.parse_event('{"id":"a","op":"restock","sku":"S","qty":true}')

    def test_rejects_float_quantity(self):
        with self.assertRaises(ValueError):
            codec.parse_event('{"id":"a","op":"restock","sku":"S","qty":1.5}')

    def test_rejects_zero_or_negative_quantity(self):
        with self.assertRaises(ValueError):
            codec.parse_event('{"id":"a","op":"restock","sku":"S","qty":0}')

    def test_rejects_empty_id(self):
        with self.assertRaises(ValueError):
            codec.parse_event('{"id":"","op":"restock","sku":"S","qty":1}')

    def test_space_is_nonempty_id(self):
        ev = codec.parse_event('{"id":" ","op":"restock","sku":"S","qty":1}')
        self.assertEqual(ev['id'], ' ')

    def test_rejects_reserve_bad_pair(self):
        with self.assertRaises(ValueError):
            codec.parse_event('{"id":"r","op":"reserve","request":"q","lines":[["a"]]}')

    def test_rejects_reserve_non_list_lines(self):
        with self.assertRaises(ValueError):
            codec.parse_event('{"id":"r","op":"reserve","request":"q","lines":"x"}')


if __name__ == '__main__':
    unittest.main()
